// Single registrar for the offline service worker (generated by vite-plugin-pwa).
// Status is only "ready" after verifying the engine, game code and page are in Cache Storage.
export type OfflineStatus = "unsupported" | "preparing" | "ready" | "error";
type Listener = (s: OfflineStatus, detail?: string) => void;

const PROJECT_ID = "2b16136d-f4bf-4710-99be-72c008a6e328";
let status: OfflineStatus = "unsupported";
let detail = "";
const listeners = new Set<Listener>();
const set = (s: OfflineStatus, d = "") => {
  status = s;
  detail = d;
  listeners.forEach((l) => l(s, d));
};
export const subscribe = (l: Listener) => (listeners.add(l), l(status, detail), () => listeners.delete(l));

function refused(): boolean {
  if (!import.meta.env.PROD) return true;
  if (window.self !== window.top) return true;
  const h = window.location.hostname.toLowerCase();
  const first = h.split(".")[0];
  if (/\.(lovable\.app|gpt-eng\.com|gptengineer\.run)$/.test(h)) {
    if (/^(?:id-preview|preview)(?:-[a-z0-9]+)?--.+$/.test(first)) return true;
    if (first === `project--${PROJECT_ID}-dev`) return true;
  }
  if (/(^|\.)lovableproject(-dev)?\.com$/.test(h)) return true;
  if (/(^|\.)beta\.lovable\.dev$/.test(h)) return true;
  if (new URLSearchParams(window.location.search).get("sw") === "off") return true;
  return false;
}

async function unregisterOwn() {
  const regs = await navigator.serviceWorker.getRegistrations();
  await Promise.all(
    regs.filter((r) => r.active?.scriptURL.endsWith("/sw.js") || r.installing?.scriptURL.endsWith("/sw.js")).map((r) => r.unregister()),
  );
}

const withTimeout = <T,>(p: Promise<T>, ms: number) =>
  Promise.race([p, new Promise<never>((_, rej) => setTimeout(() => rej(new Error("tiempo agotado")), ms))]);

async function verify(): Promise<void> {
  // Cache the page itself through the SW (NetworkFirst stores it).
  const page = await withTimeout(fetch("/", { cache: "no-store" }), 15000);
  if (!page.ok) throw new Error("no se pudo guardar la pantalla del juego");
  const keys = await caches.keys();
  const urls = new Set<string>();
  for (const k of keys) for (const r of await (await caches.open(k)).keys()) urls.add(new URL(r.url).pathname);
  const need: [string, (p: string) => boolean][] = [
    ["motor", (p) => p === "/wasm/fairy-stockfish.wasm"],
    ["worker", (p) => /\/assets\/worker-.*\.js$/.test(p)],
    ["juego", (p) => /\/assets\/Game-.*\.js$/.test(p)],
    ["pantalla", (p) => p === "/"],
  ];
  const missing = need.filter(([, t]) => ![...urls].some(t)).map(([n]) => n);
  if (missing.length) throw new Error("faltan: " + missing.join(", "));
}

let started = false;
export async function prepareOffline() {
  if (typeof window === "undefined" || !("serviceWorker" in navigator)) return;
  if (refused()) {
    await unregisterOwn().catch(() => {});
    return;
  }
  set("preparing");
  try {
    if (!started) {
      started = true;
      await navigator.serviceWorker.register("/sw.js", { scope: "/" });
    }
    await withTimeout(navigator.serviceWorker.ready, 60000);
    if (!navigator.serviceWorker.controller) {
      await withTimeout(
        new Promise<void>((res) => navigator.serviceWorker.addEventListener("controllerchange", () => res(), { once: true })),
        60000,
      );
    }
    await verify();
    set("ready");
  } catch (e) {
    set("error", navigator.onLine ? (e as Error).message : "sin conexión");
  }
}
